select count(*) / 1 as executed
from  executions e 
where e.timestamp > (select max(e2.timestamp) from executions e2) - 1::bigint * 1000 * 1000 * 1000;

select count(*) / 1 as canceled
from  cancellations c 
where c.timestamp > (select max(e.timestamp) from executions e) - 1::bigint * 1000 * 1000 * 1000;

